/**
 * @openelement/router — the UnoCSS provider's DEV channel (alpha15 stage 2B).
 *
 * The build's documents are qualified by the probe fixture's own artifacts;
 * this suite qualifies the half that has no build: a real dev server, over the
 * same fixture, serving
 *
 * - the DOCUMENT sheet from a `text/css` endpoint the head links (generated by
 *   the engine, not compiled by Vite's CSS graph — a generated-document
 *   provider has no graph entry, and dev must deliver the same text production
 *   does);
 * - the COMPONENT sheet from the versioned endpoint the dev DSD declares, with
 *   the client adapter behind the provider's own specifier.
 *
 * The fixture is a workspace member with its own `unocss` install, so the
 * adapter resolves the engine exactly as it does in a packed consumer.
 *
 * The watcher's own reaction to an edit IS covered — the last row edits the
 * fixture's `uno.config.ts` and asserts both sheets move. The harness boots the
 * dev server with the WS channel off, so the notification is observed on
 * `server.ws.send` rather than over a socket.
 */

import { createServer as createHttpServer } from 'node:http';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type { Plugin } from 'vite';
import type { ViteDevServer } from 'vite';
import { afterAll, expect, test } from 'vitest';
import { openElement } from '../src/vite/index.ts';

const FIXTURE_DIR = join(import.meta.dirname!, '../../../tests/fixtures/router-unocss-probe');

interface DevHandle {
  base: string;
  server: ViteDevServer;
  close: () => Promise<void>;
}

const handles: DevHandle[] = [];

afterAll(async () => {
  for (const handle of handles.splice(0)) await handle.close();
});

/** Boot a real dev server over the fixture, loopback-only. */
async function bootDev(plugins: Plugin[], root = FIXTURE_DIR): Promise<DevHandle> {
  const { createServer } = await import('vite');
  const previousCwd = process.cwd();
  process.chdir(root);
  let server: ViteDevServer;
  try {
    server = await createServer({
      root,
      logLevel: 'silent',
      configFile: false,
      oxc: { jsx: { runtime: 'automatic', importSource: '@openelement/element' } },
      server: { middlewareMode: true, ws: false },
      plugins,
    });
  } finally {
    process.chdir(previousCwd);
  }
  const httpServer = createHttpServer((request, response) => {
    server.middlewares(request, response, () => {
      response.statusCode = 404;
      response.end('not found');
    });
  });
  await new Promise<void>((resolve, reject) => {
    httpServer.once('error', reject);
    httpServer.listen(0, '127.0.0.1', resolve);
  });
  const address = httpServer.address();
  if (address === null || typeof address !== 'object') throw new Error('dev server did not bind');
  const handle: DevHandle = {
    base: `http://127.0.0.1:${address.port}`,
    server,
    close: async () => {
      await new Promise<void>((resolve) => httpServer.close(() => resolve()));
      await server.close();
    },
  };
  handles.push(handle);
  return handle;
}

/** The document one dev URL answers. */
async function fetchText(url: string): Promise<string> {
  return await fetch(url).then((response) => response.text());
}

test('the dev document links the ENGINE-generated sheet and that URL answers it', async () => {
  const handle = await bootDev(openElement());
  const doc = await fetchText(`${handle.base}/`);

  const href = /<link rel="stylesheet" href="([^"]*unocss-document\.[^"]+\.css)" \/>/.exec(
    doc,
  )?.[1];
  expect(href, 'the dev head links the document sheet the engine generated').toBeDefined();
  expect(href, 'a generated sheet is not the marked DSD channel').not.toContain(
    'data-oe-static-styles',
  );

  const css = await fetchText(`${handle.base}${href}`);
  expect(css, 'the token source reached the dev sheet').toContain('--color-foreground');
  expect(css, 'the declared token source’s @import was inlined').toContain(':where(html)');
  expect(css, 'the page’s admitted utilities compiled').toMatch(/\.px-6\s*\{/);
  expect(css, 'the application declared the entry, so the reset is in the sheet').toContain(
    'box-sizing: border-box',
  );
});

test('a theme source url() target keeps its source base and answers the real bytes in dev', async () => {
  // The fixture's declared token source references `./probe-swatch.svg` NEXT
  // TO ITSELF. The dev sheet is served from `/.openElement/<engine>-document.…
  // .css`, so a target left relative to the source would be a request the dev
  // server cannot answer. The provider rebases it onto the sheet's base; the
  // request the sheet then makes resolves to the actual file and the real
  // bytes come back — constructed here as the browser would construct it,
  // from the served sheet's own URL.
  const handle = await bootDev(openElement());
  const doc = await fetchText(`${handle.base}/`);
  const href = /<link rel="stylesheet" href="([^"]*unocss-document\.[^"]+\.css)" \/>/.exec(
    doc,
  )?.[1];
  expect(href, 'the dev head links the document sheet').toBeDefined();
  const css = await fetchText(`${handle.base}${href}`);
  const target = /--probe-swatch:\s*url\('([^']+)'\)/.exec(css)?.[1];
  expect(target, 'the swatch reference survives into the dev sheet').toBeDefined();
  expect(
    target,
    'the reference is not the source-relative spelling (it must resolve from the sheet URL)',
  ).not.toBe('./probe-swatch.svg');
  const resolved = new URL(target!, `${handle.base}${href}`).href;
  const response = await fetch(resolved);
  expect(response.status, 'the rebased reference answers 200').toBe(200);
  expect(response.headers.get('content-type'), 'the real asset, as its own type').toContain(
    'image/svg',
  );
  expect(await response.text(), 'the real bytes, not a 404 page').toContain('<rect');
});

test('the dev DSD declares the component sheet and the adapter carries the sheet protocol', async () => {
  const handle = await bootDev(openElement());
  const doc = await fetchText(`${handle.base}/`);

  const card = doc.slice(doc.indexOf('<probe-unocss-card'), doc.indexOf('</probe-unocss-card>'));
  expect(card, 'the shadow component is DSD-rendered').toContain(
    '<template shadowrootmode="open">',
  );
  expect(card, 'no inline <style> in the dev DSD').not.toContain('<style');
  const componentHref = /href="([^"]*unocss-components\.[^"]+\.css)"/.exec(card)?.[1];
  expect(componentHref, 'the dev DSD declares the versioned component sheet').toBeDefined();

  const sheet = await fetchText(`${handle.base}${componentHref}`);
  expect(sheet, 'the shadow utilities compiled').toMatch(/\.gap-2\s*\{/);
  expect(sheet, 'the shadow sheet carries no reset').not.toContain('box-sizing: border-box');

  const adapter = await fetchText(`${handle.base}/@id/__x00__oe-style-components-dev.js`);
  expect(adapter, 'one shared sheet per realm').toContain('__openElementComponentSheet');
  expect(adapter, 'filled by replace(), never a DOM node').toContain('sheet.replace(');
  expect(adapter, 'no style/link node is ever created').not.toContain('createElement');
});

test('the dev client entry imports the selected provider’s component-sheet adapter', async () => {
  // Dev/build channel identity (KR-4): the generated client entry must
  // register the component sheet exactly as the build does — build-client.ts
  // resolves the adapter from the SELECTED provider's integration, so the
  // client's expectedStyleLinks can recognize the DSD-declared link and the
  // hydration claim accepts its own template. A provider-gated or
  // Tailwind-hardcoded declaration would leave a UnoCSS dev app with no
  // registered sheet, and every island upgrade would fail closed with
  // "unexpected static stylesheet resource".
  const handle = await bootDev(openElement());
  // The dev island client resolves its island set from the process cwd at
  // request time — the shape of every real dev process (`pnpm dev` runs at
  // the project root). Pin it for the request, as the real process would.
  const previousCwd = process.cwd();
  process.chdir(FIXTURE_DIR);
  try {
    const entry = await fetchText(`${handle.base}/client/islands/client.js`);
    expect(
      entry,
      'the dev client entry registers the component-sheet adapter the selected provider owns',
    ).toContain('oe-style-components-dev');
  } finally {
    process.chdir(previousCwd);
  }
});

test('the sheet URL is versioned, so a second render declares the same resource', async () => {
  const handle = await bootDev(openElement());
  const doc = await fetchText(`${handle.base}/`);
  const href = /href="([^"]*unocss-document\.[^"]+\.css)"/.exec(doc)?.[1];
  expect(href, 'the document declares a versioned resource').toBeDefined();

  // The version is a digest of the served facts, so a second document at the
  // same state declares the same resource (no churn), and the endpoint is
  // `no-store` — a reload always receives the current compile.
  const response = await fetch(`${handle.base}${href}`);
  expect(response.headers.get('cache-control')).toBe('no-store');
  expect(response.headers.get('content-type')).toContain('text/css');
  const second = await fetchText(`${handle.base}/`);
  const secondHref = /href="([^"]*unocss-document\.[^"]+\.css)"/.exec(second)?.[1];
  expect(secondHref, 'an unchanged state keeps one resource identity').toBe(href);
});

test('a uno.config.ts edit re-points the served head link at a new versioned URL', async () => {
  // The generated-path dev contract: the rebuilt generator re-points the head
  // link, not just the bytes behind the old URL. The link is baked twice —
  // applyResolvedOptions refreshes state.headExtrasValue, but the entry
  // DESCRIPTOR captured the old value and the virtual entry renders from the
  // descriptor — so the move must rebuild the descriptor and invalidate the
  // entry module, or every page keeps serving the stale link forever while
  // the sheet behind it has already moved (the packed consumer's dev leg
  // pinned exactly this).
  const configPath = join(FIXTURE_DIR, 'uno.config.ts');
  const original = readFileSync(configPath, 'utf8');
  try {
    const handle = await bootDev(openElement());
    const hrefBefore = /href="([^"]*unocss-document\.[^"]+\.css)"/.exec(
      await fetchText(`${handle.base}/`),
    )?.[1];
    expect(hrefBefore, 'the document declares a versioned resource').toBeDefined();

    writeFileSync(
      configPath,
      original.replace('presets: [presetWind4()]', 'presets: [presetWind4({ important: true })]'),
      'utf8',
    );
    let hrefAfter: string | undefined;
    for (let attempt = 0; attempt < 40; attempt += 1) {
      await new Promise((resolve) => setTimeout(resolve, 250));
      hrefAfter = /href="([^"]*unocss-document\.[^"]+\.css)"/.exec(
        await fetchText(`${handle.base}/`),
      )?.[1];
      if (hrefAfter !== undefined && hrefAfter !== hrefBefore) break;
    }
    expect(hrefAfter, 'the served head link re-pointed at a new version').not.toEqual(hrefBefore);
    expect(hrefAfter, 'the new link answers the recompiled sheet').toBeDefined();
    const moved = await fetch(`${handle.base}${hrefAfter}`);
    expect(moved.status).toBe(200);
    expect(moved.headers.get('content-type')).toContain('text/css');
  } finally {
    writeFileSync(configPath, original, 'utf8');
  }
});

/** Both dev sheets as the served document declares them. */
async function devSheets(
  handle: DevHandle,
): Promise<{ documentHref: string; componentHref: string; document: string; component: string }> {
  const doc = await fetchText(`${handle.base}/`);
  const documentHref = /href="([^"]*unocss-document\.[^"]+\.css)"/.exec(doc)?.[1];
  const card = doc.slice(doc.indexOf('<probe-unocss-card'), doc.indexOf('</probe-unocss-card>'));
  const componentHref = /href="([^"]*unocss-components\.[^"]+\.css)"/.exec(card)?.[1];
  expect(documentHref, 'the document declares its sheet').toBeDefined();
  expect(componentHref, 'the DSD declares the component sheet').toBeDefined();
  return {
    documentHref: documentHref!,
    componentHref: componentHref!,
    document: await fetchText(`${handle.base}${documentHref}`),
    component: await fetchText(`${handle.base}${componentHref}`),
  };
}

/**
 * Poll both sheets until one satisfies `ready`, or return the last read.
 *
 * The engine's configuration is an input to BOTH sheets, so the row that proves
 * a rebuild has to see it in both: the edit below flips the preset's
 * `important` option, which changes the declaration every compiled utility
 * carries — in the component sheet as much as in the document sheet, unlike a
 * theme colour, whose value the component sheet only ever references
 * (`var(--colors-primary)`) and whose declaration the theme layer owns.
 */
async function waitForSheets(
  handle: DevHandle,
  hrefs: { documentHref: string; componentHref: string },
  ready: (sheets: { document: string; component: string }) => boolean,
): Promise<{ document: string; component: string }> {
  const deadline = Date.now() + 15_000;
  let last = { document: '', component: '' };
  while (Date.now() < deadline) {
    last = {
      document: await fetchText(`${handle.base}${hrefs.documentHref}`),
      component: await fetchText(`${handle.base}${hrefs.componentHref}`),
    };
    if (ready(last)) return last;
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
  return last;
}

/**
 * The engine's own configuration is an INPUT to both sheets, so editing it has
 * to reach them the way editing a component does.
 *
 * Both channels were built once and never rebuilt: the component channel's
 * integration was memoized and its relevance test never matched a configuration
 * file, and the document channel's change identity was made of the theme, the
 * reset policy and the candidate set — none of which a `uno.config.ts` edit
 * moves — so its watcher saw the file, compared an unchanged identity and
 * returned without invalidating anything. The new configuration simply never
 * arrived at either sheet.
 *
 * The URL is deliberately NOT asserted to move: the dev URL is stable by
 * contract (the DSD link is baked into the served HTML when a page renders
 * while the adapter is fetched later, so the two samples legitimately disagree
 * on a version), and freshness rides the content at that URL plus the
 * notification telling the client to take it.
 */
test('a uno.config.ts edit rebuilds the generator and reaches both dev sheets', async () => {
  const configPath = join(FIXTURE_DIR, 'uno.config.ts');
  const original = readFileSync(configPath, 'utf8');
  expect(original, 'the fixture builds its default preset with no options').toContain(
    'presets: [presetWind4()]',
  );
  try {
    const handle = await bootDev(openElement());
    const sent: unknown[] = [];
    handle.server.ws.send = (...args: unknown[]) => {
      sent.push(args[0]);
    };

    const before = await devSheets(handle);
    expect(before.component, 'the component sheet carries the role utility').toContain(
      '.bg-primary\\/14',
    );
    // The token source carries `!important` of its own, so the option under
    // test is measured by how many declarations carry it, not by its presence.
    const importantCount = (css: string) => (css.match(/!important/g) ?? []).length;
    const beforeCounts = {
      document: importantCount(before.document),
      component: importantCount(before.component),
    };

    writeFileSync(
      configPath,
      original.replace('presets: [presetWind4()]', 'presets: [presetWind4({ important: true })]'),
      'utf8',
    );
    const after = await waitForSheets(
      handle,
      before,
      (sheets) => importantCount(sheets.component) > beforeCounts.component,
    );
    expect(
      importantCount(after.component),
      'the component sheet was recompiled from the new configuration',
    ).toBeGreaterThan(beforeCounts.component);
    expect(
      importantCount(after.document),
      'the document sheet was recompiled from it too',
    ).toBeGreaterThan(beforeCounts.document);
    expect(
      sent.length,
      'the change was announced to the client, not applied silently',
    ).toBeGreaterThan(0);

    // The URL contract split by channel: the COMPONENT sheet's dev URL is
    // stable (it recompiles per request in place), while the DOCUMENT sheet's
    // link RE-POINTS at a new versioned URL — the generated-path contract
    // (dev-style.ts's moveVersion, setFrameworkStylesheets's "a re-resolution
    // re-points the framework's link"). This suite's earlier pin asserted the
    // document URL stayed stable; that pinned the incomplete move — the head
    // extras were baked into an entry descriptor nothing rebuilt, so the link
    // could never re-point — as if it were the contract. The descriptor now
    // rebuilds on the move, and the dedicated row above pins the re-point
    // end-to-end.
    const current = await devSheets(handle);
    expect(
      current.documentHref,
      'the dev document link re-pointed at a new versioned URL',
    ).not.toBe(before.documentHref);
    expect(current.componentHref, 'the dev component URL stays stable').toBe(before.componentHref);

    // A second edit is served from the rebuilt generator, not from one that was
    // rebuilt once and then froze again.
    writeFileSync(configPath, original, 'utf8');
    const final = await waitForSheets(
      handle,
      before,
      (sheets) => importantCount(sheets.component) === beforeCounts.component,
    );
    expect(importantCount(final.component), 'the second edit reached the component sheet').toBe(
      beforeCounts.component,
    );
    expect(importantCount(final.document), 'the second edit reached the document sheet too').toBe(
      beforeCounts.document,
    );
  } finally {
    writeFileSync(configPath, original, 'utf8');
  }
});

test('a uno.config.ts edit reaches both dev sheets when the project root lives under the OS temp directory', async () => {
  // The macOS temp-root shape: /var is a symlink to /private/var, and the
  // file-events stream reports the REALPATH while the engine's configuration
  // loader reports the path AS GIVEN. A configuration input matched by string
  // identity never recognizes its own file's change, the generator never
  // rebuilds, and the edit never reaches either sheet — the packed-consumer
  // lane hit exactly this with a scratch app under the OS temp directory.
  // Identity must be a fact about the FILE, not about the spelling it was
  // reached through.
  const { cpSync, rmSync, symlinkSync } = await import('node:fs');
  const { tmpdir } = await import('node:os');
  const { mkdtemp } = await import('node:fs/promises');
  const scratch = await mkdtemp(join(tmpdir(), 'openelement-unocss-tmp-root-'));
  try {
    for (const entry of ['app', 'openelement.config.ts', 'uno.config.ts', 'package.json']) {
      cpSync(join(FIXTURE_DIR, entry), join(scratch, entry), { recursive: true });
    }
    // The engine resolves from the app root's own tree; the copy borrows the
    // fixture's node_modules so the copied root resolves the same packages.
    symlinkSync(join(FIXTURE_DIR, 'node_modules'), join(scratch, 'node_modules'), 'dir');
    const handle = await bootDev(openElement(), scratch);
    const configPath = join(scratch, 'uno.config.ts');
    const original = readFileSync(configPath, 'utf8');
    const before = await devSheets(handle);
    expect(before.component, 'the component sheet carries the role utility').toContain(
      '.bg-primary\\/14',
    );
    const importantCount = (css: string) => (css.match(/!important/g) ?? []).length;
    const beforeCounts = {
      document: importantCount(before.document),
      component: importantCount(before.component),
    };

    writeFileSync(
      configPath,
      original.replace('presets: [presetWind4()]', 'presets: [presetWind4({ important: true })]'),
      'utf8',
    );
    const after = await waitForSheets(
      handle,
      before,
      (sheets) => importantCount(sheets.component) > beforeCounts.component,
    );
    expect(
      importantCount(after.component),
      'the temp-dir root did not isolate the configuration watcher: the component sheet was recompiled',
    ).toBeGreaterThan(beforeCounts.component);
    expect(
      importantCount(after.document),
      'the document sheet was recompiled from the new configuration too',
    ).toBeGreaterThan(beforeCounts.document);
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
});
